package com.example.starter.slot.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;

import java.util.List;

/**
 * 航班时刻系列申请入参。
 *
 * @param requestId  申请幂等键，同一系列重复提交必须使用相同 requestId
 * @param airline    航司二字码，如 CA
 * @param flightNo   航班号，如 CA1234
 * @param slotTime   申请时刻（HH:mm，须为 5 分钟粒度，如 08:35）
 * @param weeks      覆盖周列表（周序号，从 1 开始），一个系列的多周分配整体成功或整体回滚
 */
public record SlotSeriesRequest(
        @NotBlank String requestId,
        @NotBlank String airline,
        @NotBlank String flightNo,
        @NotBlank
        @Pattern(regexp = "^([01]\\d|2[0-3]):[0-5]\\d$", message = "slotTime 必须为 HH:mm 格式")
        String slotTime,
        @NotNull @NotEmpty List<@NotNull Integer> weeks) {
}

package com.example.starter.slot.dto;

import java.util.List;

/**
 * 冲突明细：某一时刻某一周已被其他航司占用。
 *
 * @param slotTime 冲突时刻（HH:mm）
 * @param week     冲突周序号
 * @param holder   当前占有的航司二字码
 */
public record SlotConflictView(String slotTime, int week, String holder) {
}

package com.example.starter.slot.dto;

/**
 * 单条时刻占用记录视图。
 *
 * @param slotTime 时刻（HH:mm）
 * @param week     周序号
 * @param type     占用类型：RETAINED（历史优先权保留）或 POOL（公共池分配）
 */
public record SlotAllocationView(String slotTime, int week, String type) {
}

package com.example.starter.slot.dto;

import java.util.List;

/**
 * 系列申请结果。
 *
 * @param requestId   申请幂等键
 * @param airline     航司二字码
 * @param flightNo    航班号
 * @param status      结果状态：ALLOCATED（全部分配成功）
 * @param allocations 已占用的时刻/周清单
 */
public record SlotResultView(String requestId, String airline, String flightNo,
                             String status, List<SlotAllocationView> allocations) {
}

package com.example.starter.slot.dto;

import java.util.List;

/**
 * 系列退回结果。
 *
 * @param requestId 申请幂等键
 * @param released  本次释放的时刻/周清单
 */
public record ReturnResultView(String requestId, List<SlotAllocationView> released) {
}

