package com.example.starter.slot;

import com.example.starter.slot.dto.PublicationView;
import com.example.starter.slot.dto.ReturnResultView;
import com.example.starter.slot.dto.SlotResultView;
import com.example.starter.slot.dto.SlotSeriesRequest;
import org.springframework.stereotype.Service;

/**
 * 航班时刻协调核心服务：系列申请（含历史优先权裁决）、退回释放、快照发布。
 */
@Service
public class SlotService {

    /**
     * 提交系列申请。按 requestId 幂等；同键同参返回首次结果，同键异参抛 409。
     * 多周分配整体成功或整体回滚。
     */
    public SlotResultView apply(SlotSeriesRequest request) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 退回已分配系列，释放其全部时刻。发布后迟到退回不改变已发布快照。
     */
    public ReturnResultView release(String requestId) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 查询系列当前状态。
     */
    public SlotResultView getRequest(String requestId) {
        throw new UnsupportedOperationException("not implemented");
    }

    /**
     * 发布本期分配表快照；发布后本期冻结，重复发布幂等成功。
     */
    PublicationView publish() {
        throw new UnsupportedOperationException("not implemented");
    }
}

package com.example.starter.slot;

import com.example.starter.slot.dto.PublicationView;
import com.example.starter.slot.dto.ReturnResultView;
import com.example.starter.slot.dto.SlotResultView;
import com.example.starter.slot.dto.SlotSeriesRequest;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 航班时刻协调 REST 入口。
 */
@RestController
@RequestMapping("/api/slots")
public class SlotController {

    private final SlotService slotService;

    public SlotController(SlotService slotService) {
        this.slotService = slotService;
    }

    /**
     * 提交系列申请：历史优先权达标（>=80%）自动保留占用，否则进入公共池竞争。
     */
    @PostMapping("/requests")
    public ResponseEntity<SlotResultView> apply(@Valid @RequestBody SlotSeriesRequest request) {
        return ResponseEntity.status(HttpStatus.CREATED).body(slotService.apply(request));
    }

    /**
     * 查询系列申请状态。
     */
    @GetMapping("/requests/{requestId}")
    public SlotResultView getRequest(@PathVariable String requestId) {
        return slotService.getRequest(requestId);
    }

    /**
     * 退回系列，释放其占用的全部时刻。
     */
    @PostMapping("/requests/{requestId}/return")
    public ReturnResultView release(@PathVariable String requestId) {
        return slotService.release(requestId);
    }

    /**
     * 发布本期分配表快照，发布后本期冻结。
     */
    @PostMapping("/publications")
    public PublicationView publish() {
        return slotService.publish();
    }
}

package com.example.starter.slot;

import com.example.starter.slot.dto.ErrorView;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常到错误响应的映射。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(SlotConflictException.class)
    public ResponseEntity<ErrorView> handleConflict(SlotConflictException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new ErrorView(ex.getCode(), ex.getMessage(), ex.getConflicts()));
    }

    @ExceptionHandler(PeriodFrozenException.class)
    public ResponseEntity<ErrorView> handleFrozen(PeriodFrozenException ex) {
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(ErrorView.of("PERIOD_FROZEN", ex.getMessage()));
    }

    @ExceptionHandler(SlotNotFoundException.class)
    public ResponseEntity<ErrorView> handleNotFound(SlotNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(ErrorView.of("NOT_FOUND", ex.getMessage()));
    }

    @ExceptionHandler({MethodArgumentNotValidException.class, HttpMessageNotReadableException.class,
            IllegalArgumentException.class})
    public ResponseEntity<ErrorView> handleBadRequest(Exception ex) {
        String message = ex instanceof MethodArgumentNotValidException manve
                && manve.getBindingResult().getFieldError() != null
                ? manve.getBindingResult().getFieldError().getField() + ": "
                + manve.getBindingResult().getFieldError().getDefaultMessage()
                : ex.getMessage();
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(ErrorView.of("VALIDATION_FAILED", message));
    }
}

