        start.countDown();
        List<String> results = new ArrayList<>();
        for (Future<String> f : futures) results.add(f.get(30, TimeUnit.SECONDS));
        pool.shutdown();
        assertEquals(1, results.stream().filter("OK"::equals).count());
        assertEquals(threads - 1, results.stream().filter("CONFLICT"::equals).count());
        Integer holders = jdbc.queryForObject("SELECT COUNT(*) FROM slot_allocation WHERE slot_time='08:30' AND week_no=1", Integer.class);
