        assertThrows(SlotConflictException.class,
                () -> slotService.apply(req("REQ-M", "CA", "CA100", "08:30", 1, 2)));
    }

    @Test
    void releaseFreesSlotImmediatelyForOthers() {
        slotService.apply(req("REQ-A", "CA", "CA100", "08:30", 1));
